public static class CodexLuaRound2SyncSample {
 public static string Run() {
  var output=new System.Text.StringBuilder("PROFILE:sync;forcedGC=false;hot=20000;dto=2000;callback=5000;compile=10;cold=2\n");
  foreach(var b in LuaRuntimeProbe.Backends.LuaBackendRegistry.All) {
   var c=LuaRuntimeProbe.Harness.BenchConfig.Default();
   c.CleanBaselineBeforeEachRow=false;c.HotIterations=20000;c.BridgeDirectIterations=20000;
   c.DtoIterations=2000;c.CallbackIterations=5000;c.CompileIterations=10;c.ColdInitIterations=2;
   c.TotalWorkBudgetMs=8000;c.PerMetricWorkBudgetMs=2000;
   var r=LuaRuntimeProbe.Harness.ProbeBench.Run(b,c);
   output.AppendLine(b.Info.Id+"|status="+r.Status+"|wall="+r.WallMs+"|setup="+r.SetupMs+"|"+r.FlagCensus());
   foreach(var row in r.Rows) output.AppendLine(row.Metric+"|n="+row.PerformedIterations+"|us="+row.PerOpMicros+"|ok="+row.ChecksumOk+"|flag="+row.Flag);
  }
  return output.ToString();
 }
}
